   214  char* parse_content_length(char* const buffer, const char* const end,
   215                  int* const length)
   216  {
   217          int number;
   218          char *p;
   219          int  size;
   220
   221          p = buffer;
   222          /* search the begining of the number */
   223          while ( p<end && (*p==' ' || *p=='\t' ||
   224          (*p=='\n' && (*(p+1)==' '||*(p+1)=='\t')) ))
   225                  p++;
   226          if (p==end)
   227                  goto error;
   228          /* parse the number */
   229          size = 0;
   230          number = 0;
   231          while (p<end && *p>='0' && *p<='9') {
   232                  number = number*10 + (*p)-'0';
   233                  size ++;
   234                  p++;
   235          }
   236          if (p==end || size==0)
   237                  goto error;
   238          /* now we should have only spaces at the end */
   239          while ( p<end && (*p==' ' || *p=='\t' ||
   240          (*p=='\n' && (*(p+1)==' '||*(p+1)=='\t')) ))
   241                  p++;
   242          if (p==end)
   243                  goto error;
   244          /* the header ends proper? */
   245          if ( (*(p++)!='\n') && (*(p-1)!='\r' || *(p++)!='\n' ) )
   246                  goto error;
   247
   248          *length = number;
   249          return p;
   250  error:
   251          LM_ERR("parse error near char [%d][%c]\n", *p, *p);
   252          return 0;
   253  }
